/** Runtime site geometry (local metres, [east, north]) — generated by scripts/build-site-runtime.ts. */
import raw from '../../data/derived/site-runtime.json';
import { hasFault } from '../app/faults.ts';

export type EN = readonly [number, number];
export interface SlipGeom {
  id: string;
  dock: string;
  corners: readonly EN[];
  inner: EN;
  outer: EN;
  centroid: EN;
  headingDeg: number;
}
export interface SiteRuntime {
  slips: readonly SlipGeom[];
  headwalks: Readonly<Record<string, { osmWay: number; kind: string; line: readonly EN[] }>>;
  land: readonly { id: string; ring: readonly EN[]; holes: readonly (readonly EN[])[] }[];
  osmContext: readonly { osmId: number; kind: string; ring: readonly EN[] }[];
  masses: readonly { id: string; kind: string; label: string; ring: readonly EN[] }[];
  lines: readonly { id: string; kind: string; label: string; line: readonly EN[]; widthM: number }[];
  canal: readonly EN[];
}

/**
 * Structural check of the runtime geometry (T18). Invalid geometry is never guessed or partly drawn: the map
 * modules (3D scene and 2D plan) fail to load with a SiteGeometryError, and the list and inspector, which do
 * not depend on geometry, keep working.
 */
export class SiteGeometryError extends Error {
  override name = 'SiteGeometryError';
}
const finitePt = (p: unknown) => Array.isArray(p) && p.length === 2 && p.every((n) => typeof n === 'number' && Number.isFinite(n));
export function validateSite(site: SiteRuntime): string[] {
  const issues: string[] = [];
  if (!Array.isArray(site.slips) || site.slips.length === 0) return ['no slips'];
  const seen = new Set<string>();
  for (const s of site.slips) {
    if (!/^[A-E]-\d{2}$/.test(s.id) || seen.has(s.id)) issues.push(`slip id ${String(s.id)}`);
    seen.add(s.id);
    if (!Array.isArray(s.corners) || s.corners.length < 3 || !s.corners.every(finitePt)) issues.push(`${s.id}: corners`);
    for (const k of ['inner', 'outer', 'centroid'] as const) if (!finitePt(s[k])) issues.push(`${s.id}: ${k}`);
    if (!Number.isFinite(s.headingDeg)) issues.push(`${s.id}: heading`);
  }
  for (const [id, h] of Object.entries(site.headwalks ?? {})) if (!Array.isArray(h.line) || h.line.length < 2 || !h.line.every(finitePt)) issues.push(`headwalk ${id}`);
  for (const l of site.land ?? []) if (!l.ring.every(finitePt)) issues.push(`land ${l.id}`);
  return issues;
}

/** `?debug&fault=geometry` (dev/test only): one slip corner becomes NaN, as a corrupt geometry file would. */
function withFault(site: SiteRuntime): SiteRuntime {
  if (!hasFault('geometry')) return site;
  const [first, ...rest] = site.slips;
  return { ...site, slips: [{ ...first!, corners: [[Number.NaN, 0], ...first!.corners.slice(1)] }, ...rest] };
}

const loaded = withFault(raw as unknown as SiteRuntime);
const siteIssues = validateSite(loaded);
if (siteIssues.length > 0) throw new SiteGeometryError(`Map geometry failed ${siteIssues.length} check(s): ${siteIssues.slice(0, 3).join('; ')}`);
export const SITE = loaded;
const byId = new Map(SITE.slips.map((s) => [s.id, s]));
export const slipGeom = (id: string): SlipGeom | undefined => byId.get(id);
export { MODELLED_DOCKS } from './docks.ts';
